// 1 | 41 timestamp ms | 10 machine | 12 sequence
//
//  41 bits ms   ≈ 69 years from a custom epoch
//  10 bits      = 1,024 generators
//  12 bits      = 4,096 per ms → ~4.1M IDs/sec/machine

const EPOCH = 1700000000000; // custom, not 1970 — buys the full 69 years
const MACHINE_BITS = 10, SEQ_BITS = 12;
const MAX_SEQ = (1 << SEQ_BITS) - 1; // 4095

let lastMs = -1, seq = 0;

function nextId(machineId) {
  let now = Date.now();

  if (now === lastMs) {
    seq = (seq + 1) & MAX_SEQ;
    if (seq === 0) now = waitNextMs(lastMs); // exhausted this ms
  } else {
    seq = 0;
  }
  lastMs = now;

  return (BigInt(now - EPOCH) << BigInt(MACHINE_BITS + SEQ_BITS))
       | (BigInt(machineId) << BigInt(SEQ_BITS))
       | BigInt(seq);
}

function monotonicNow() {
  const wall = Date.now();

  if (wall < lastMs) {
    const drift = lastMs - wall;
    if (drift > 5000) throw new Error(`clock regressed ${drift}ms — refusing`);
    return lastMs; // small rewind: keep issuing, let sequence absorb it
  }
  return wall;
}

function decode(id) {
  const seq     = id & BigInt(MAX_SEQ);
  const machine = (id >> BigInt(SEQ_BITS)) & BigInt((1 << MACHINE_BITS) - 1);
  const ms      = (id >> BigInt(MACHINE_BITS + SEQ_BITS)) + BigInt(EPOCH);

  return {
    at: new Date(Number(ms)),
    machine: Number(machine),
    seq: Number(seq),
  };
}

// Sortable ENOUGH for:  feed pagination, cursor paging, debugging
// NOT sufficient for:   causal ordering, financial sequencing
//
// Those need logical clocks or a consensus sequencer — far more
// expensive than three bit shifts.
